import{_ as e,o as n,c as a,ag as o}from"./chunks/framework.CAXxHpAX.js";const h=JSON.parse('{"title":"Deepsight 工程设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"guide/engineering-arch.md","filePath":"guide/engineering-arch.md","lastUpdated":null}'),l={name:"guide/engineering-arch.md"};function t(r,s,i,p,c,d){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="deepsight-工程设计文档" tabindex="-1">Deepsight 工程设计文档 <a class="header-anchor" href="#deepsight-工程设计文档" aria-label="Permalink to &quot;Deepsight 工程设计文档&quot;">​</a></h1><h2 id="_1-项目文件架构" tabindex="-1">1. 项目文件架构 <a class="header-anchor" href="#_1-项目文件架构" aria-label="Permalink to &quot;1. 项目文件架构&quot;">​</a></h2><p>为了确保 <strong>“重边缘、轻中心”</strong> 的设计哲学在落地时得以高效实现，项目采用 <strong>Monorepo（单仓）</strong> 架构。结构设计强调数据管线的物理映射，并在底层网络极限压缩与顶层 LLM 语义透明之间做出了严谨的模块解耦。</p><h3 id="_1-1-目录结构" tabindex="-1">1.1 目录结构 <a class="header-anchor" href="#_1-1-目录结构" aria-label="Permalink to &quot;1.1 目录结构&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deepsight/</span></span>
<span class="line"><span>├── docs/                   # [文档] 架构设计、开发手册与用户指南</span></span>
<span class="line"><span>├── proto/                  # [契约] Protobuf 接口定义 (单一事实来源)</span></span>
<span class="line"><span>│   ├── v1/                 # 核心 RPC 接口 (基于 oneof 联合体，保留动态字典同步机制)</span></span>
<span class="line"><span>│   ├── common/             # 全局枚举与基础类型</span></span>
<span class="line"><span>│   └── modules/            # 模块载荷 (network, storage 等强类型定义)</span></span>
<span class="line"><span>├── api/                    # [生成] 自动生成的 Go/C 契约代码 (受 Git 显式追踪保护)</span></span>
<span class="line"><span>├── 3rd/libbpf              # [拉取] Git Submodule 拉取的底层 libbpf 库</span></span>
<span class="line"><span>├── probe/                  # [边缘] Deepsight 探针 (C + Go 双体架构)</span></span>
<span class="line"><span>│   ├── bpf/                # [内核态] eBPF C 源码 (基于 CO-RE 编写)</span></span>
<span class="line"><span>│   ├── loader/             # 基于 cilium/ebpf 的探针生命周期管理</span></span>
<span class="line"><span>│   ├── exporter/           # [上行出口] 处理 PushTelemetry 单向流</span></span>
<span class="line"><span>│   ├── transformer/        # [用户态] 符号翻译、字典 ID 分配、令牌桶限流 (熔断保护)</span></span>
<span class="line"><span>│   ├── executor/           # [下行执行] 监听 TaskChannel 追踪指令</span></span>
<span class="line"><span>│   └── cmd/                # 探针入口程序</span></span>
<span class="line"><span>├── server/                 # [中心] Deepsight 复合网关 (Go)</span></span>
<span class="line"><span>│   ├── ingester/           # [接入层] gRPC 服务端，执行字典反向映射与语义延迟翻译</span></span>
<span class="line"><span>│   ├── buffer/             # [记忆引擎] 冷热分级缓存 (纯内存 Metrics + 内嵌 KV 事件持久化)</span></span>
<span class="line"><span>│   ├── mcp/                # [外交官] MCP 协议适配与大模型 Prompt 约束</span></span>
<span class="line"><span>│   ├── dispatcher/         # [调度层] 负责长短任务智能分流 (同步阻塞 vs 凭证 Ticket)</span></span>
<span class="line"><span>│   └── cmd/                # 网关入口程序 (常态化守护进程)</span></span>
<span class="line"><span>├── internal/               # [私有] 跨模块共享的私有库</span></span>
<span class="line"><span>│   └── deps/               # 固化底层外部运行时 (如 ebpf/grpc) 防 go mod tidy 误删</span></span>
<span class="line"><span>├── configs/                # [配置] 环境参数与 MCP Prompts 专家 SOP 模板</span></span>
<span class="line"><span>├── scripts/                # [工具] 自动化运维与 DevOps 脚本矩阵</span></span>
<span class="line"><span>│   ├── setup/              # 系统环境与项目级初始化配置</span></span>
<span class="line"><span>│   ├── dev/                # 特权隔离的编译与本地测试入口</span></span>
<span class="line"><span>│   └── tests/              # 内核负载刺激与探针触发源</span></span>
<span class="line"><span>└── tests/                  # [集成] 需要 Root 权限的端到端 (E2E) 测试链</span></span></code></pre></div><h3 id="_1-2-模块设计要点" tabindex="-1">1.2 模块设计要点 <a class="header-anchor" href="#_1-2-模块设计要点" aria-label="Permalink to &quot;1.2 模块设计要点&quot;">​</a></h3><ul><li><strong>网络与语义解耦</strong>：底层 RPC 通信采用增量动态字典压缩长字符串以保护物理带宽。网关 <code>ingester</code> 模块负责执行“延迟翻译”，将整型 ID 还原为纯文本，结合强类型 <code>oneof</code> 联合体，确保直接为 LLM 提供所见即所得的明文 JSON。</li><li><strong>状态一致性与会话隔离</strong>：引入基于 <code>session_token</code> 的字典生命周期管理。面对进程重启或网络闪断，Probe 会在重连时上报全量字典；Server 端则通过安全覆盖当前活跃字典并颁发新会话 Token，完美解耦探针物理状态的脆弱性与历史数据的连贯性。</li><li><strong>边缘熔断保护</strong>：在 <code>transformer</code> 模块强制引入令牌桶限流。当内核发生高频异常风暴时触发同质化事件截断，仅向上传递高价值样本与截断计数，确保宿主机 CPU 安全。</li><li><strong>长短任务智能调度</strong>：MCP 交互基于耗时采取分流策略。短任务（&lt;15s）采用同步阻塞模式直接返回闭环结果；长耗时任务（&gt;15s）下发任务凭证（Ticket），配合 Prompt 强制约束 LLM 结束当前回合，稍后凭 Ticket 提取数据。</li><li><strong>双体探针架构</strong>：Probe 采用 C + Go 的黄金组合。C 语言负责受限内核态的安全“采矿”，Go 语言负责用户态的符号翻译、字典压缩与高并发网络传输。</li></ul><h2 id="_2-项目管理" tabindex="-1">2. 项目管理 <a class="header-anchor" href="#_2-项目管理" aria-label="Permalink to &quot;2. 项目管理&quot;">​</a></h2><p>项目采用 <strong>“契约驱动”</strong> 模式，为了支撑 eBPF 复杂底层与双语言开发，工程基础底座由“三剑客”与分层测试体系共同构建：</p><h3 id="_2-1-基础设施三剑客" tabindex="-1">2.1 基础设施三剑客 <a class="header-anchor" href="#_2-1-基础设施三剑客" aria-label="Permalink to &quot;2.1 基础设施三剑客&quot;">​</a></h3><ol><li><strong>环境依赖 (<code>scripts/setup/</code>)</strong>： <ul><li><code>init.sh</code> 负责 C 编译链、eBPF 工具链以及 Go 环境的系统级拉起。</li><li><code>setup.sh</code> 负责生成项目配置（<code>vmlinux.h</code>, <code>.clangd</code>），并在本地注入 Git Hooks。</li></ul></li><li><strong>构建与防线 (<code>Makefile</code>)</strong>： <ul><li>彻底剥离运行属性，专注静态处理。</li><li>执行 <code>make build</code> 闭环双端编译，利用 <code>go generate ./probe/...</code> 动态扫描并挂载 eBPF 编译链。</li><li>利用 <code>make fmt</code> 与 <code>make lint</code> 守卫代码底线（已绑定至 pre-commit hook）。</li></ul></li><li><strong>特权运行与调试 (<code>scripts/dev/</code>)</strong>： <ul><li><code>run_probe.sh</code> 与 <code>run_server.sh</code>，专门处理提权（<code>sudo</code>）、环境变量配置和复杂的调试前置条件，屏蔽直接操作二进制的风险。</li></ul></li></ol><h3 id="_2-2-测试分层策略" tabindex="-1">2.2 测试分层策略 <a class="header-anchor" href="#_2-2-测试分层策略" aria-label="Permalink to &quot;2.2 测试分层策略&quot;">​</a></h3><p>根据 eBPF 项目的特性，测试分为两道物理隔离的防线：</p><ul><li><strong>纯用户态逻辑测试 (Unit Tests)</strong>：就近存放（如 <code>transformer_test.go</code>），与业务代码同目录混排，不触碰内核，通过 <code>make test</code> 极速验证。</li><li><strong>端到端集成测试 (E2E Tests)</strong>：统一放置于根目录 <strong><code>tests/</code></strong> 文件夹中。此类测试强依赖真实内核环境和 Root 权限，专门用于验证探针注入和事件消费链路。</li></ul><h3 id="_2-3-资产管理" tabindex="-1">2.3 资产管理 <a class="header-anchor" href="#_2-3-资产管理" aria-label="Permalink to &quot;2.3 资产管理&quot;">​</a></h3><ul><li><strong>提示词即代码 (Prompt as Code)</strong>：将 LLM 专家诊断 SOP (Prompts) 作为核心系统资产，统一存放于 <code>configs/</code> 目录。支持 Server 启动时热加载，实现 AI 诊断逻辑与核心代码的生命周期解耦。</li></ul><h2 id="_3-项目交付" tabindex="-1">3. 项目交付 <a class="header-anchor" href="#_3-项目交付" aria-label="Permalink to &quot;3. 项目交付&quot;">​</a></h2><p>Deepsight 的交付物旨在实现 <strong>“单一二进制分发、冷热状态自闭环”</strong>。</p><h3 id="_3-1-产出形态" tabindex="-1">3.1 产出形态 <a class="header-anchor" href="#_3-1-产出形态" aria-label="Permalink to &quot;3.1 产出形态&quot;">​</a></h3><ul><li><strong>Probe (边缘)</strong>： <ul><li><strong>形态</strong>：包含嵌入式 eBPF 字节码的单一 Go 二进制文件。</li><li><strong>职责</strong>：极致轻量化，专注数据提取、限流与高压缩比推送，不承载持久化逻辑。</li></ul></li><li><strong>Server (中心)</strong>： <ul><li><strong>形态</strong>：复合型有状态守护进程 (Stateful Daemon)。</li><li><strong>特性</strong>：采用冷热分级存储架构。纯内存 FIFO 数组保障 Metrics 极速响应，底层轻量级内嵌 KV 引擎（如 bbolt）结合特征防抖算法，强制以 100% 延迟翻译后的明文形态落盘，保障核心故障 Events 断电不丢失。</li></ul></li></ul><h3 id="_3-2-部署与网络关系" tabindex="-1">3.2 部署与网络关系 <a class="header-anchor" href="#_3-2-部署与网络关系" aria-label="Permalink to &quot;3.2 部署与网络关系&quot;">​</a></h3><ul><li><strong>权限受控</strong>：Probe 必须以 <code>root</code> 权限运行，以满足 eBPF 挂载及内核符号表读取的需求。</li><li><strong>内向连接模型</strong>：Probe 启动后主动出站连接 Server 的 gRPC 端口，完美适配 VPC 防火墙拦截外部流量的规则。Server 仅被动监听内部数据流并对外暴露受控的 MCP HTTP 接口。</li></ul><h2 id="_4-实验性工程边界声明" tabindex="-1">4. 实验性工程边界声明 <a class="header-anchor" href="#_4-实验性工程边界声明" aria-label="Permalink to &quot;4. 实验性工程边界声明&quot;">​</a></h2><p>为了在 V1.0 阶段快速验证“大模型感知系统底层”的核心链路，防止被 Day-2 的运维合规需求拖慢研发节奏，本项目在工程实现上确立以下“极致务实”的边界纪律：</p><ol><li><strong>内核支持策略 (CO-RE Only)</strong>： <ul><li>全面采用 CO-RE (Compile Once – Run Everywhere) 技术栈。</li><li><strong>基线要求</strong>：目标宿主机必须开启 BTF (BPF Type Format) 特性，建议 Linux Kernel &gt;= 5.8。</li><li><strong>工程取舍</strong>：拒绝向后兼容无 BTF 的老旧内核，拒绝引入 BCC 运行时编译链，以确保 Probe 是一个极度纯净的单一 Go 二进制文件。</li></ul></li><li><strong>部署形态 (Bare Metal First)</strong>： <ul><li>首发版本仅面向物理机/虚拟机 (Bare Metal / VM)。</li><li><strong>工程取舍</strong>：采用简单的 Systemd 守护进程部署即可。暂不考虑 Kubernetes DaemonSet 容器化部署带来的权限提权 (<code>privileged</code>) 及命名空间穿透等繁杂问题。</li></ul></li><li><strong>安全与认证 (Zero-Friction Sec)</strong>： <ul><li><strong>gRPC 链路</strong>：采用明文 TCP 传输，暂不引入 mTLS 双向认证。</li><li><strong>MCP 接口</strong>：暂不设立 API Key 或 JWT 鉴权，避免复杂的审计日志库。</li><li><strong>防御底线</strong>：安全防御彻底依赖于 VPC 网络层隔离。Server 端的所有监听端口（gRPC 与 HTTP）必须在配置中严格绑定为内网 IP 或 <code>127.0.0.1</code>，严禁绑定 <code>0.0.0.0</code> 暴露至公网。</li></ul></li><li><strong>自身可观测性 (Log as Metrics)</strong>： <ul><li><strong>工程取舍</strong>：暂不引入 Prometheus、Grafana 等重量级时序指标系统。</li><li><strong>替代方案</strong>：状态监控全面退化为日志。利用 Go 1.21+ 的 <code>log/slog</code> 将 Probe 的限流截断次数、Server 的内存水位等信息，以结构化 JSON 格式定时输出至标准输出。同时保留一个极简的 <code>system://health</code> MCP Resource 供大模型执行基础探活。</li></ul></li></ol>`,25)])])}const u=e(l,[["render",t]]);export{h as __pageData,u as default};
